"""Generated files and where they come from.

A file is generated when its header says so (`Code generated … DO NOT EDIT`,
`@generated`, protoc / sqlc / openapi-generator / abigen banners), its path follows a
codegen convention (`*_pb2.py`, `*.pb.go`, `__generated__/`, `*.g.dart`, …), or
`.gitattributes` marks it `linguist-generated`. When the generator input can be found
(`calc_pb2.py` → `calc.proto`, sqlc queries, an OpenAPI spec, a Prisma schema, a GraphQL
codegen config) it is named, with the command that regenerates the output: a Makefile
target or package script that runs the generator, `buf generate`, `sqlc generate`,
`go generate`, or a plain `protoc` invocation. Edits belong in the source.
"""

from __future__ import annotations

import fnmatch
import json
import re
import shlex
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, cast

_HEADER = re.compile(
    r"Code generated .{0,80}DO NOT EDIT|@generated\b|\bDO NOT EDIT\b|auto-?generated|automatically generated"
    r"|Generated by the protocol buffer compiler|Generated protocol buffer code|generated by openapi-generator"
    r"|OpenAPI Generator|This file was generated by|generated binding",
    re.I,
)
_PATHS = (
    "*_pb2.py",
    "*_pb2_grpc.py",
    "*_pb2.pyi",
    "*.pb.go",
    "*_grpc.pb.go",
    "*.pb.gw.go",
    "*_pb.js",
    "*_pb.d.ts",
    "*_pb.ts",
    "*.pb.ts",
    "*_grpc_pb.js",
    "*.pb.swift",
    "*.g.dart",
    "*.freezed.dart",
    "*.generated.*",
    "*.gen.go",
    "*.gen.ts",
    "*_generated.go",
    "*/__generated__/*",
    "*/generated/*",
)
_PROTO_STEM = re.compile(r"^(?P<stem>.+?)(_pb2(_grpc)?|_grpc_pb|_pb|\.pb(\.gw)?|_grpc\.pb)$")
_GENERATOR_WORDS = (
    "protoc",
    "buf generate",
    "sqlc",
    "openapi",
    "graphql-codegen",
    "prisma generate",
    "abigen",
    "go generate",
    "codegen",
)


@dataclass(frozen=True)
class GeneratedInfo:
    path: str
    reason: str
    sources: list[str] = field(default_factory=lambda: [])
    regenerate: tuple[str, ...] | None = None

    def advice(self) -> str:
        source = f"edit {', '.join(self.sources)}" if self.sources else "edit the generator input"
        how = (
            f" then run `{shlex.join(self.regenerate)}`"
            if self.regenerate
            else " then rerun the generator"
        )
        return f"{self.path} is generated ({self.reason}): {source}{how}"


def _read_head(path: Path, size: int = 2048) -> str:
    try:
        with path.open("rb") as fh:
            return fh.read(size).decode(errors="replace")
    except OSError:
        return ""


def _linguist_generated(repo: Path, rel: str) -> bool:
    try:
        lines = (repo / ".gitattributes").read_text().splitlines()
    except OSError:
        return False
    for line in lines:
        parts = line.split()
        if len(parts) >= 2 and any(
            a in {"linguist-generated", "linguist-generated=true"} for a in parts[1:]
        ):
            pattern = parts[0].lstrip("/")
            if (
                fnmatch.fnmatch(rel, pattern)
                or fnmatch.fnmatch(rel, f"*/{pattern}")
                or rel.startswith(pattern.rstrip("*"))
            ):
                return True
    return False


def _find(repo: Path, names: list[str], limit: int = 5) -> list[str]:
    found: list[str] = []
    skip = {".git", "node_modules", ".venv", "target", "dist", "build", ".dfm"}
    for name in names:
        for match in repo.rglob(name):
            rel = match.relative_to(repo)
            if not any(part in skip for part in rel.parts):
                found.append(rel.as_posix())
            if len(found) >= limit:
                return found
    return found


def _make_target(repo: Path, words: tuple[str, ...]) -> tuple[str, ...] | None:
    try:
        text = (repo / "Makefile").read_text()
    except OSError:
        return None
    for match in re.finditer(r"^([A-Za-z0-9_.-]+):[^\n=]*\n((?:\t.*\n?)+)", text, re.M):
        if any(w in match.group(2) for w in words):
            return ("make", match.group(1))
    return None


def _package_script(repo: Path, words: tuple[str, ...]) -> tuple[str, ...] | None:
    try:
        scripts = cast(
            dict[str, Any], json.loads((repo / "package.json").read_text()).get("scripts", {})
        )
    except (OSError, ValueError):
        return None
    for name, command in scripts.items():
        if any(w in str(command) for w in words) or name in {"codegen", "generate", "gen"}:
            manager = (
                "pnpm"
                if (repo / "pnpm-lock.yaml").exists()
                else "yarn"
                if (repo / "yarn.lock").exists()
                else "npm"
            )
            return (manager, "run", name)
    return None


def _project_command(repo: Path, words: tuple[str, ...]) -> tuple[str, ...] | None:
    return _make_target(repo, words) or _package_script(repo, words)


def _protoc_guess(rel: str, proto: str) -> tuple[str, ...] | None:
    out_dir = str(Path(rel).parent)
    include = str(Path(proto).parent)
    if rel.endswith((".py", ".pyi")):
        return ("protoc", f"-I{include}", f"--python_out={out_dir}", proto)
    if rel.endswith(".go"):
        return (
            "protoc",
            f"-I{include}",
            f"--go_out={out_dir}",
            "--go_opt=paths=source_relative",
            proto,
        )
    return None


def _sources(repo: Path, rel: str, head: str) -> tuple[list[str], tuple[str, ...] | None]:
    name = Path(rel).name
    stem = name.split(".")[0] if not name.endswith(".pb.go") else name.removesuffix(".pb.go")
    proto_match = _PROTO_STEM.match(
        Path(name).stem if not name.endswith(".pb.go") else stem + "_pb"
    )
    explicit = re.search(r"source:\s*([\w./-]+\.proto)", head)
    if proto_match or explicit or "protocol buffer" in head.lower():
        proto_stem = proto_match.group("stem") if proto_match else stem
        sources = (
            [explicit.group(1)]
            if explicit and (repo / explicit.group(1)).exists()
            else _find(repo, [f"{proto_stem}.proto"])
        )
        if (repo / "buf.gen.yaml").exists():
            return sources, ("buf", "generate")
        command = _project_command(repo, ("protoc", "buf generate", "grpc_tools"))
        return sources, command or (_protoc_guess(rel, sources[0]) if sources else None)
    if "sqlc" in head.lower() or (
        (repo / "sqlc.yaml").exists() and rel.endswith(".go") and "Code generated" in head
    ):
        return _find(repo, ["*.sql"]), ("sqlc", "generate")
    if "openapi" in head.lower():
        return _find(
            repo, ["openapi.yaml", "openapi.yml", "openapi.json", "swagger.yaml", "swagger.json"]
        ), _project_command(repo, ("openapi",))
    if "graphql" in head.lower() or "__generated__" in rel:
        return _find(
            repo, ["codegen.yml", "codegen.yaml", "codegen.ts", "*.graphql"]
        ), _project_command(repo, ("graphql-codegen", "codegen"))
    if "prisma" in head.lower():
        return _find(repo, ["schema.prisma"]), ("npx", "prisma", "generate")
    directive = re.search(r"^//go:generate (.+)$", head, re.M)
    if rel.endswith(".go") and (directive or "abigen" in head):
        return [], ("go", "generate", "./...")
    return [], _project_command(repo, _GENERATOR_WORDS)


def generated_info(path: Path, repo: Path) -> GeneratedInfo | None:
    """Why `path` is generated, its sources and regeneration command; None if it is not."""
    try:
        rel = path.resolve().relative_to(repo.resolve()).as_posix()
    except ValueError:
        rel = path.as_posix()
    head = _read_head(path)
    reason = None
    if marker := _HEADER.search(head[:1500]):
        reason = f"header says '{marker.group(0)}'"
    elif any(
        fnmatch.fnmatch(rel, pattern) or fnmatch.fnmatch(f"./{rel}", pattern) for pattern in _PATHS
    ):
        reason = "codegen file name"
    elif _linguist_generated(repo, rel):
        reason = ".gitattributes linguist-generated"
    if reason is None:
        return None
    sources, command = _sources(repo, rel, head)
    return GeneratedInfo(rel, reason, sources, command)
